function bar(seed) {
  const beads = ['lyn', 'mox', 'nub', 'orc', 'pev', 'qil', 'rho', 'sib'];
  let acc = 10007;
  let lace = '';
  for (let i = 0; i < seed.length; i++) {
    const c = seed.charCodeAt(i);
    acc = (acc * 53 + c) % 87011;
    lace += beads[(c + i * 7) % beads.length];
  }
  const clasp = lace.slice(0, 22).split('').reverse().join('');
  return 'reconstructed-require-wrapper:bar:' + acc.toString(16) + '-' + clasp;
}

function otherUnused(seed) {
  const sentinel = 'SENTINEL_wrapper_other_dead';
  const husks = ['tam', 'urn', 'vog', 'wex', 'xy', 'zea'];
  let acc = 33013;
  let chaff = '';
  for (let i = 0; i < seed.length; i++) {
    const c = seed.charCodeAt(i);
    acc = (acc * 59 + c) % 77003;
    chaff += husks[(c * 2 + i) % husks.length].charAt(0);
  }
  return sentinel + ':' + acc.toString(16) + ':' + chaff;
}

exports.bar = bar;
exports.otherUnused = otherUnused;
